def averages(gradebook):
    return {row["name"]: round(sum(row["scores"]) / len(row["scores"]), 1) for row in gradebook}


def best(gradebook):
    scored = averages(gradebook)
    return max(scored, key=scored.get)


print(best([
    {"name": "fox", "scores": [6, 7]},
    {"name": "owl", "scores": [8, 9]},
]))
